{
  "name": "cedula360-mcp",
  "version": "1.16.0",
  "description": "Servidor MCP de Cédula 360 — verificación de información pública oficial colombiana (ADRES, Rama Judicial, DIAN, RUES, sanciones/PEP, Legal IA, MiniMax) vía tu API key c360_live_*.",
  "type": "module",
  "bin": {
    "cedula360-mcp": "src/server.js"
  },
  "main": "src/server.js",
  "files": [
    "src",
    "README.md"
  ],
  "scripts": {
    "start": "node src/server.js",
    "start:http": "MCP_HTTP=1 node src/server.js"
  },
  "engines": {
    "node": ">=18"
  },
  "keywords": [
    "mcp",
    "model-context-protocol",
    "cedula360",
    "colombia",
    "kyc",
    "compliance",
    "claude",
    "claude-code",
    "opencode",
    "cursor",
    "llm"
  ],
  "homepage": "https://cedula360.tech/#mcp",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/alexanderoviedofadul/cedula360-co.git",
    "directory": "mcp"
  },
  "author": "Cédula 360",
  "license": "MIT",
  "publishConfig": {
    "access": "public"
  },
  "dependencies": {
    "@modelcontextprotocol/sdk": "^1.12.0",
    "express": "^4.21.2",
    "zod": "^3.24.1"
  }
}
